SELECT distinct temp_no,temp_type,remark, temp_name,books_no,segment1, data_state, updated_by, updated_time
FROM tms_cit_journal_temp


        AND remark = #{remark}


        AND temp_type = #{templateType}


        AND stream_type = #{flowType}


        AND temp_name LIKE CONCAT('%', #{templateName}, '%')


ORDER BY updated_time DESC

SELECT COUNT(*)
FROM tms_cit_journal_temp


        AND remark = #{remark}


        AND temp_type = #{templateType}


        AND stream_type = #{flowType}


        AND temp_name LIKE CONCAT('%', #{templateName}, '%')
